                        used.add(color[nb])
                c = 0
                while c in used:
                    c += 1
                color[v] = c
            if is_valid(color):
                nc = num_colors(color)
                if nc < best_num:
                    best_num = nc
                    best_color = color[:]
        return best_color

    # Welsh-Powell with random tie-breaking in degree sorting
    def welsh_powell_restarts(restarts=5):
        best_color = None
        best_num = float('inf')
        indices = list(range(n))
        for _ in range(restarts):
            # Sort by degree descending, break ties randomly
            local_random = random.Random()
            local_random.seed()
            # Create list of (degree, random, index) for sorting
            decorated = [(degree[i], local_random.random(), i) for i in indices]
            decorated.sort(key=lambda x: (-x[0], x[1]))
            order = [x[2] for x in decorated]
            color = [-1] * n
            for v in order:
                used = set()
                for nb in adj_list[v]:
                    if color[nb] != -1:
                        used.add(color[nb])
                c = 0
                while c in used:
                    c += 1
                color[v] = c
            if is_valid(color):
                nc = num_colors(color)
                if nc < best_num:
                    best_num = nc
                    best_color = color[:]
        return best_color

    # Iterated Local Search with Kempe chains and vertex relocation
    def iterated_local_search(initial_color, iterations=100):
        if not is_valid(initial_color):
            return initial_color  # fallback, though should not happen
        color = initial_color[:]
        current_num = num_colors(color)
        best_color = color[:]
        best_num = current_num
        local_random = random.Random()
        local_random.seed()

        for _ in range(iterations):
            # Try to reduce number of colors by Kempe chain swaps and relocations
            # Attempt to eliminate the highest color class
            max_color = max(color) if n > 0 else -1
            if max_color <= 0:
                break
            # List of vertices with max_color
            vertices_max = [v for v in range(n) if color[v] == max_color]
            # Shuffle to avoid bias
            local_random.shuffle(vertices_max)
            made_change = False
            for v in vertices_max:
                # Try to move v to a lower color directly
                used_by_neighbors = set()
                for nb in adj_list[v]:
                    if color[nb] != -1:
                        used_by_neighbors.add(color[nb])
                for c in range(max_color):
                    if c not in used_by_neighbors:
                        # Direct move possible
                        color[v] = c
                        made_change = True
                        break
                if made_change:
                    break
                # Try Kempe chain for each lower color
                for c in range(max_color):
                    if c in used_by_neighbors:
                        # Both colors present in neighborhood, try Kempe swap
                        comp_c = c
                        comp_max = max_color
                        # BFS to find Kempe chain component of v in colors {c, max_color}
                        visited = set()
                        stack = [v]
                        visited.add(v)
                        while stack:
                            x = stack.pop()
                            for nb in adj_list[x]:
                                if nb not in visited and (color[nb] == comp_c or color[nb] == comp_max):
                                    visited.add(nb)
                                    stack.append(nb)
                        # Check if any neighbor of v colored c is in the component
                        conflict = False
                        for nb in adj_list[v]:
                            if color[nb] == comp_c and nb in visited:
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap
                            for x in visited:
                                if color[x] == comp_c:
                                    color[x] = comp_max
                                else:
                                    color[x] = comp_c
                            made_change = True
                            break
                if made_change:
                    break
            if made_change:
                # After change, compute new number of colors
                current_num = num_colors(color)
                if current_num < best_num:
                    best_num = current_num
                    best_color = color[:]
                # Optionally, try to improve by local search (not implemented for brevity)
            else:
                # Could not reduce max_color, try next lower color class in next iteration? 
                # For simplicity, we break if no change in this iteration
                # In practice, we might continue with lower color, but we limit iterations.
                pass
        return best_color

    # Run all algorithms and select the best
    best_coloring = None
    best_num_colors = float('inf')

    # List of coloring functions to try, each with restarts
    coloring_funcs = [
        ("dsatur", dsatur_restarts),
        ("rlf", rlf_restarts),
        ("smallest_last", smallest_last_restarts),
        ("welsh_powell", welsh_powell_restarts)
    ]

    for name, func in coloring_funcs:
        try:
            col = func()
            if is_valid(col):
                nc = num_colors(col)
                if nc < best_num_colors:
                    best_num_colors = nc
                    best_coloring = col[:]
                    # Early exit if we achieve the theoretical lower bound (clique size not computed, but if 1 color and no edges, or if we suspect optimal)
                    # We can compute a simple lower bound: max degree + 1 is an upper bound, lower bound is size of max clique -> not computed.
                    # Instead, if we get a coloring that matches the degeneracy + 1, we might stop, but degeneracy not computed here.
                    # For now, we run all quick methods.
        except Exception:
            continue

    # Apply iterated local search to the best coloring found
    if best_coloring is not None and is_valid(best_coloring):
        try:
            reduced = iterated_local_search(best_coloring, iterations=50)
            if is_valid(reduced):
                nc = num_colors(reduced)
                if nc < best_num_colors:
                    best_num_colors = nc
                    best_coloring = reduced
        except Exception:
            pass

    # Fallback: if no valid coloring found, use greedy in random order
    if best_coloring is None or not is_valid(best_coloring):
        local_random = random.Random()
        local_random.seed()
        order = list(range(n))
        local_random.shuffle(order)
        color = [-1] * n
        for v in order:
            used = set()
            for nb in adj_list[v]:
                if color[nb] != -1:
                    used.add(color[nb])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        best_coloring = color

    return best_coloring
